int gs_window_face_height(void)
{
    return gs_win_face_height;
}

int gs_window_face_ascent(void)
{
    return gs_win_face_baseline;
}

int gs_window_face_width_n(const char *text, size_t len)
{
    size_t i;
    int wide = 0;

    if (text == NULL)
        return 0;
    for (i = 0; i < len && text[i] != '\0'; i++) {
        int code = (unsigned char)text[i] - GS_WIN_GLYPH_FIRST;

        if (code >= 0 && code < GS_WIN_GLYPH_COUNT)
            wide += gs_win_face_advance[code];
    }
    return wide;
}

int gs_window_face_width(const char *text)
{
    return text == NULL ? 0 : gs_window_face_width_n(text, strlen(text));
}
